-- The version retcon (migration 0048, generated by `cargo jackioh patches retcon`, issue #1371, SPEC §11
-- R1371000, R1371001). Runs after 26_dev_accounts.sql; profiles 1 and 2 are active by then.
\set ON_ERROR_STOP on

-- As 14 does for 0025: every row the suite seeds carries a name the retcon keeps, so the
-- migration renamed nothing when run.sh applied it; this check seeds rows under the old names, as
-- production holds them, applies the migration again over them, and rolls back. The names overlap
-- (the old v0.3.4 is the new v0.2.7b while the new v0.3.4 is the old v0.3.12), so each row must be
-- renamed exactly once. This file spells old names on purpose: the retcon's tree rewrite skips it.

\echo '### R1371000: the version retcon renames each row''s catalog version once ###'
begin;
do $$
declare
  p1 constant uuid := '11111111-1111-1111-1111-111111111111';
  p2 constant uuid := '22222222-2222-2222-2222-222222222222';
  rec_of constant text := '{"pilots": {"p1": "ai", "p2": "ai"}, "game": {"turns": 9}}';
begin
  insert into public.cards (id, card_index, name, set_id, type, tags, rarity, token, cost, catalog_version)
  values ('r1371-a', '1371.1', 'Card under v0.3.17', 'Core', 'Unit', '{}', 'Common', false, '1'::jsonb, 'v0.3.17'),
         ('r1371-b', '1371.2', 'Card under v0.3.4', 'Core', 'Unit', '{}', 'Common', false, '1'::jsonb, 'v0.3.4'),
         ('r1371-c', '1371.3', 'Card under v0.3.12', 'Core', 'Unit', '{}', 'Common', false, '1'::jsonb, 'v0.3.12');
  update app.settings set value = '"v0.3.17"' where key = 'catalog_version';
  perform set_config('r1371.grants', (select count(*)::text from public.collection_grants), true);

  insert into public.decks (id, profile_id, name, cards, catalog_version)
  values ('d1371000-0000-4000-8000-000000000001', p1, 'Under v0.3.17', '["core-001"]', 'v0.3.17'),
         ('d1371000-0000-4000-8000-000000000002', p1, 'Under core-1', '["core-001"]', 'core-1');
  insert into public.matches (id, status, seed, p1_profile_id, p2_profile_id, p1_deck, p2_deck,
                              catalog_version, ceiling_at, started_at, ended_at)
  values ('e1371000-0000-4000-8000-000000000004', 'over', 'r1371-4', p1, p2, '[]', '[]', 'v0.3.4', now(), now(), now()),
         ('e1371000-0000-4000-8000-000000000012', 'over', 'r1371-12', p1, p2, '[]', '[]', 'v0.3.12', now(), now(), now());
  insert into public.match_checkpoints (match_id, seq, nonce, catalog_version, rules, checkpoint_version, body, body_hash)
  values ('e1371000-0000-4000-8000-000000000012', 1, 'n', 'v0.3.12', 'r', 1, '{}', 'h');
  insert into public.series (id, p1_profile_id, p2_profile_id, status, next_match_id, version, catalog_version, state)
  values ('f1371000-0000-4000-8000-000000000001', p1, p2, 'playing', 'f1371000-0000-4000-8000-0000000000a1', 3,
          'v0.3.12', '{"sides": [], "games": [], "seedBase": "s"}');

  -- Two development ids whose new names would meet the other's old one, a series that spells a
  -- version, a live record, and one whose detail the purge emptied.
  insert into public.game_records (id, source, mode, patch, record, folded)
  select g.id, g.source, 'random', g.patch,
         case when g.emptied then null
              else rec_of::jsonb || jsonb_build_object('id', g.id, 'source', g.source, 'mode', 'random', 'patch', g.patch) end,
         g.emptied
    from (values ('e1371000-0000-4000-8000-0000000000aa', 'live', 'v0.3.4', false),
                 ('dev:v0.3.4:r1371:1', 'dev', 'v0.3.4', false),
                 ('dev:v0.3.12:r1371:1', 'dev', 'v0.3.12', false),
                 ('dev:v0.3.7b:learned-v0.3.7b-20261018-5:2', 'dev', 'v0.3.7b', false),
                 ('dev:v0.3.17:r1371:9', 'dev', 'v0.3.17', true)) as g (id, source, patch, emptied);

  -- The totals key on the patch: the old v0.3.4's row and the old v0.3.12's change places.
  insert into public.record_totals (patch, source, mode, p1_pilot, p2_pilot, records)
  values ('v0.3.4', 'dev', 'random', 'ai', 'ai', 4), ('v0.3.12', 'dev', 'random', 'ai', 'ai', 12);
  insert into public.card_totals (patch, source, mode, pilot, card, stats, co)
  values ('v0.3.4', 'dev', 'random', 'ai', 'core-001', '{"n": 4}', '{"core-002": [1, 1, "dev:v0.3.4:r1371:1", 0, 0]}'),
         ('v0.3.12', 'dev', 'random', 'ai', 'core-001', '{"n": 12}', '{"core-002": [1, 0, "dev:v0.3.12:r1371:1", 1, 2]}');
  insert into public.decklist_totals (patch, list, deck, games, wins, first_record, first_seat)
  values ('v0.3.4', 'l', '[]', 4, 1, 'dev:v0.3.4:r1371:1', 0), ('v0.3.12', 'l', '[]', 12, 6, 'dev:v0.3.12:r1371:1', 1);

  -- The season in play is the old live version's.
  delete from public.rated_games where season_id in ('v0.3', 'v0.4');
  delete from public.season_ranks where season_id in ('v0.3', 'v0.4');
  delete from public.seasons where id in ('v0.3', 'v0.4');
  insert into public.seasons (id, patch_version, started_at) values ('v0.3', 'v0.3.1', now() - interval '9 days');
  insert into public.season_ranks (season_id, profile_id, games, wins, losses, draws, ladder, floor, streak,
                                   peak_ladder, peak_jlorious, updated_at)
  values ('v0.3', p1, 3, 2, 1, 0, 7, 0, 1, 7, null, now());
  insert into public.rated_games (id, kind, season_id, patch_version, catalog_version,
    p1_profile_id, p1_bot_id, p1_pilot, p1_before, p1_after, p1_rank_before, p1_rank_after,
    p2_profile_id, p2_bot_id, p2_pilot, p2_before, p2_after, p2_rank_before, p2_rank_after,
    winner_side, reason, ended_at)
  values ('a1371000-0000-4000-8000-0000000000a1', 'match', 'v0.3', 'v0.3.12', 'v0.3.4', p1, null, 'human',
          '{"rating":1000,"deviation":350,"volatility":0.06}'::jsonb,
          '{"rating":1016,"deviation":340,"volatility":0.06}'::jsonb, null, null,
          null, 'ai-easy', 'ai',
          '{"rating":1000,"deviation":350,"volatility":0.06}'::jsonb,
          '{"rating":984,"deviation":340,"volatility":0.06}'::jsonb, null, null,
          0, 'hero-death', now());
end $$;

\i /tmp/0048_version_retcon.sql

do $$
declare
  v text;
  n int;
begin
  if app.catalog_version() <> 'v0.4.0c' then
    raise exception 'FAIL (R1371000): the live version is %, expected v0.4.0c', app.catalog_version();
  end if;
  if (select count(*)::text from public.collection_grants) <> current_setting('r1371.grants') then
    raise exception 'FAIL (R1371000): the rename granted cards';
  end if;
  select string_agg(id || '=' || catalog_version, ',' order by id) into v from public.cards where id like 'r1371-%';
  if v <> 'r1371-a=v0.4.0c,r1371-b=v0.2.7b,r1371-c=v0.3.4' then
    raise exception 'FAIL (R1371000): the cards are %', v;
  end if;

  -- The deck saved under v0.3.17 loads as v0.4.0c; one under another name is left.
  select catalog_version into v from public.decks where id = 'd1371000-0000-4000-8000-000000000001';
  if v <> 'v0.4.0c' then
    raise exception 'FAIL (R1371000): the deck saved under v0.3.17 is under %, expected v0.4.0c', v;
  end if;
  select catalog_version into v from public.decks where id = 'd1371000-0000-4000-8000-000000000002';
  if v <> 'core-1' then
    raise exception 'FAIL (R1371000): a deck under core-1 was renamed to %', v;
  end if;

  select string_agg(catalog_version, ',' order by seed) into v from public.matches where seed like 'r1371-%';
  if v <> 'v0.3.4,v0.2.7b' then
    raise exception 'FAIL (R1371000): the matches are % (r1371-12, r1371-4)', v;
  end if;
  if (select catalog_version from public.match_checkpoints where match_id = 'e1371000-0000-4000-8000-000000000012') <> 'v0.3.4' then
    raise exception 'FAIL (R1371000): the checkpoint was not renamed once';
  end if;
  if (select catalog_version || '@' || version from public.series where id = 'f1371000-0000-4000-8000-000000000001') <> 'v0.3.4@4' then
    raise exception 'FAIL (R1371000): the series is not v0.3.4 at version 4';
  end if;

  select string_agg(id || '=' || patch, ',' order by id) into v from public.game_records
   where id like 'dev:%r1371%' or id like 'dev:%learned%' or id = 'e1371000-0000-4000-8000-0000000000aa';
  if v <> 'dev:v0.2.7b:r1371:1=v0.2.7b,dev:v0.3.1:learned-v0.3.1-20261018-5:2=v0.3.1,dev:v0.3.4:r1371:1=v0.3.4,dev:v0.4.0c:r1371:9=v0.4.0c,e1371000-0000-4000-8000-0000000000aa=v0.2.7b' then
    raise exception 'FAIL (R1371000): the game records are %', v;
  end if;
  select count(*) into n from public.game_records
   where (id like 'dev:%r1371%' or id like 'dev:%learned%' or id = 'e1371000-0000-4000-8000-0000000000aa')
     and record is not null
     and (record ->> 'id' <> id or record ->> 'patch' <> patch or record -> 'versions' <> '2'::jsonb
          or record #>> '{game,turns}' <> '9');
  if n <> 0 then
    raise exception 'FAIL (R1371000): % records'' copies do not match their row, or lost their detail', n;
  end if;
  if exists (select 1 from public.game_records where id like 'dev:~%') then
    raise exception 'FAIL (R1371000): a record kept its passing name';
  end if;

  select string_agg(patch || '=' || records, ',' order by patch) into v from public.record_totals where patch in ('v0.2.7b', 'v0.3.4', 'v0.3.12');
  if v <> 'v0.2.7b=4,v0.3.4=12' then
    raise exception 'FAIL (R1371000): the record totals are %', v;
  end if;
  select string_agg(patch || '=' || (stats ->> 'n') || ':' || (co #>> '{core-002,2}'), ',' order by patch) into v
    from public.card_totals where card = 'core-001' and patch in ('v0.2.7b', 'v0.3.4', 'v0.3.12');
  if v <> 'v0.2.7b=4:dev:v0.2.7b:r1371:1,v0.3.4=12:dev:v0.3.4:r1371:1' then
    raise exception 'FAIL (R1371000): the card totals are %', v;
  end if;
  select string_agg(patch || '=' || games || ':' || first_record, ',' order by patch) into v
    from public.decklist_totals where list = 'l';
  if v <> 'v0.2.7b=4:dev:v0.2.7b:r1371:1,v0.3.4=12:dev:v0.3.4:r1371:1' then
    raise exception 'FAIL (R1371000): the decklist totals are %', v;
  end if;

  select patch_version || '/' || catalog_version || '/' || season_id into v from public.rated_games
   where id = 'a1371000-0000-4000-8000-0000000000a1';
  if v <> 'v0.3.4/v0.2.7b/v0.4' then
    raise exception 'FAIL (R1371000, R1371001): the rated game is %', v;
  end if;

  -- R1371001: the season in play takes the new live version's name, with its ranks; no new season.
  if exists (select 1 from public.seasons where id = 'v0.3') then
    raise exception 'FAIL (R1371001): the season v0.3 kept its name';
  end if;
  if (select patch_version from public.seasons where id = 'v0.4') <> 'v0.2.5f' then
    raise exception 'FAIL (R1371001): the season v0.4 is not the old v0.3 renamed';
  end if;
  if (select ladder from public.season_ranks where season_id = 'v0.4' and profile_id = '11111111-1111-1111-1111-111111111111') <> 7 then
    raise exception 'FAIL (R1371001): the rank did not follow its season';
  end if;
  raise notice 'OK (R1371000, R1371001): every row renamed once, the copies kept, the season in play renamed';
end $$;
rollback;
